import{_ as t,o,c as r,ag as a}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"RustChat Architecture — Current State Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/current-state-analysis-2026-04-26.md","filePath":"architecture/current-state-analysis-2026-04-26.md","lastUpdated":1777305067000}'),d={name:"architecture/current-state-analysis-2026-04-26.md"};function s(i,e,n,c,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="rustchat-architecture-—-current-state-analysis" tabindex="-1">RustChat Architecture — Current State Analysis <a class="header-anchor" href="#rustchat-architecture-—-current-state-analysis" aria-label="Permalink to &quot;RustChat Architecture — Current State Analysis&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-26<br><strong>Scope:</strong> Full-stack architecture review across backend, frontend, database, realtime, and infrastructure<br><strong>Method:</strong> Document review + parallel codebase exploration (6 focused subagents)</p><hr><h2 id="executive-summary" tabindex="-1">Executive Summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive Summary&quot;">​</a></h2><p>RustChat is a <strong>functionally mature, self-hosted team collaboration platform</strong> with a well-conceived architecture that generally matches its documentation. However, the codebase exhibits signs of <strong>rapid feature growth without corresponding architectural maintenance</strong>. The most critical issues are:</p><ol><li><strong>Frontend migration limbo</strong> — A clean feature-based architecture is built but the UI still runs on legacy monolithic stores</li><li><strong>Severe documentation drift</strong> — The data model doc is months behind and actively misleading</li><li><strong>Backend code organization debt</strong> — Missing repository abstraction, oversized services, and startup logic polluting the router builder</li><li><strong>Realtime memory hygiene</strong> — Unbounded growth in WebSocket subscription maps</li><li><strong>Production deployment gaps</strong> — Dev-optimized Docker Compose with no K8s manifests, monitoring, or automated backups</li></ol><table tabindex="0"><thead><tr><th>Area</th><th>Grade</th><th>Summary</th></tr></thead><tbody><tr><td>Backend API Layer</td><td><strong>B+</strong></td><td>Clean v1/v4 separation, mature WebSocket dual-protocol support, but file bloat and router pollution</td></tr><tr><td>Backend Services</td><td><strong>B-</strong></td><td>Functional and secure, but missing repository layer, god services, tight AppState coupling</td></tr><tr><td>Database / Models</td><td><strong>B</strong></td><td>Solid schema with soft deletes and JSONB flexibility, but severe doc drift and 2–3 model-schema mismatches</td></tr><tr><td>Realtime / WebSocket</td><td><strong>B+</strong></td><td>Mature cluster broadcast, session resumption, presence lifecycle, but memory leaks and v1 robustness gap</td></tr><tr><td>Frontend</td><td><strong>C+</strong></td><td>Infrastructure for clean architecture exists, but migration never completed; UI runs on legacy stores</td></tr><tr><td>Infrastructure / Deployment</td><td><strong>B-</strong></td><td>Strong security defaults and CI, but production deployment artifacts are incomplete</td></tr></tbody></table><hr><h2 id="_1-backend-api-layer" tabindex="-1">1. Backend API Layer <a class="header-anchor" href="#_1-backend-api-layer" aria-label="Permalink to &quot;1. Backend API Layer&quot;">​</a></h2><h3 id="what-works-well" tabindex="-1">What Works Well <a class="header-anchor" href="#what-works-well" aria-label="Permalink to &quot;What Works Well&quot;">​</a></h3><ul><li><strong>Clean v1/v4 separation</strong> — Native and Mattermost-compatible APIs are cleanly isolated; v4 does not leak into v1</li><li><strong>Shared WebSocket core</strong> — <code>websocket_core.rs</code> centralizes auth, presence, limits, and command handling for both endpoints</li><li><strong>Security-conscious defaults</strong> — Explicit per-route body limits (64KB / 1MB / 50MB), panic-to-JSON recovery, secure auth token transport only</li><li><strong>v4 compatibility depth</strong> — Session resumption, message replay (128-msg buffer), reconnect snapshots, binary msgpack, Mattermost event name mapping</li><li><strong>Cluster-aware presence</strong> — Redis-backed connection counting with 90s TTL heartbeats; fails closed when Redis is unavailable</li></ul><h3 id="concerns" tabindex="-1">Concerns <a class="header-anchor" href="#concerns" aria-label="Permalink to &quot;Concerns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Severity</th><th>Issue</th><th>Location</th><th>Details</th></tr></thead><tbody><tr><td>🔴 High</td><td>File size bloat</td><td><code>api/admin.rs</code> (2,591L), <code>api/oauth.rs</code> (1,961L), <code>api/v4/calls_plugin/mod.rs</code> (4,234L)</td><td>Violates &quot;thin handlers&quot; guideline; should be modularized like <code>v4/channels/</code></td></tr><tr><td>🔴 High</td><td>Startup logic in router builder</td><td><code>api/mod.rs</code></td><td>Spawns 5 background workers inside <code>router()</code> — anti-pattern</td></tr><tr><td>🟡 Medium</td><td>v1/v4 auth extractor divergence</td><td><code>api/auth.rs</code> vs <code>api/v4/extractors.rs</code></td><td><code>MmAuthUser</code> supports cookie auth; <code>AuthUser</code> does not. Some v1 endpoints already have MM-compatible routes</td></tr><tr><td>🟡 Medium</td><td>v4 501 blind spot</td><td><code>api/v4/mod.rs</code></td><td>Fallback returns structured 501 but no metrics — gaps are invisible</td></tr><tr><td>🟡 Medium</td><td>Unauthenticated WS upgrade</td><td><code>api/v4/websocket.rs</code></td><td>Accepts connection before auth for MM mobile compatibility</td></tr></tbody></table><h3 id="documented-vs-actual" tabindex="-1">Documented vs. Actual <a class="header-anchor" href="#documented-vs-actual" aria-label="Permalink to &quot;Documented vs. Actual&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Claim</th><th>Reality</th><th>Match</th></tr></thead><tbody><tr><td>&quot;Keep handlers thin; place logic in services&quot;</td><td>⚠️ Partial — v4 compat and admin handlers are thick</td><td>⚠️</td></tr><tr><td>&quot;Preserve MM API response signatures&quot;</td><td>✅ Extensive <code>mm::</code> models, <code>x-mm-compat</code> header, <code>encode_mm_id</code></td><td>✅</td></tr><tr><td>&quot;All public functions return <code>Result</code>&quot;</td><td>✅ <code>ApiResult&lt;T&gt;</code> throughout</td><td>✅</td></tr></tbody></table><hr><h2 id="_2-backend-services-layer" tabindex="-1">2. Backend Services Layer <a class="header-anchor" href="#_2-backend-services-layer" aria-label="Permalink to &quot;2. Backend Services Layer&quot;">​</a></h2><h3 id="what-works-well-1" tabindex="-1">What Works Well <a class="header-anchor" href="#what-works-well-1" aria-label="Permalink to &quot;What Works Well&quot;">​</a></h3><ul><li><strong>Good error handling</strong> — <code>AppError</code> with <code>thiserror</code>, custom error enums for complex services (<code>EmailServiceError</code>, <code>PushNotificationError</code>)</li><li><strong>Security-conscious design</strong> — Anti-enumeration in password reset, SSRF protection in webhooks, constant-time token compares</li><li><strong>Background workers</strong> — Push notifications, outgoing webhooks, Keycloak sync, reconciliation are fire-and-forget</li><li><strong>Workflow-based email</strong> — Outbox pattern with quiet hours, throttling, locale fallback</li></ul><h3 id="concerns-1" tabindex="-1">Concerns <a class="header-anchor" href="#concerns-1" aria-label="Permalink to &quot;Concerns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Severity</th><th>Issue</th><th>Details</th></tr></thead><tbody><tr><td>🔴 High</td><td><code>posts.rs</code> is a god service (1,037L)</td><td>Handles CRUD, permissions, mentions, activities, push, webhooks, playbooks, DM resurrection, WS broadcast</td></tr><tr><td>🔴 High</td><td><strong>No repository layer</strong></td><td>Services mix business logic with raw SQLx queries. Only <code>PolicyRepository</code> exists as an outlier</td></tr><tr><td>🟡 Medium</td><td><code>AppState</code> as service locator</td><td>15+ fields passed everywhere; hard to identify actual dependencies</td></tr><tr><td>🟡 Medium</td><td>Services construct other services inline</td><td><code>EmailService::new(db.clone())</code> called in multiple places instead of shared instance</td></tr><tr><td>🟡 Medium</td><td><code>unreads.rs</code> complexity</td><td>Dual Redis schemas (legacy + v2) + dirty-marker reconciler + DB fallback</td></tr><tr><td>🟡 Medium</td><td>No service traits / hard to mock</td><td>Free functions + concrete structs make unit testing without full DB/Redis impossible</td></tr></tbody></table><h3 id="documented-vs-actual-1" tabindex="-1">Documented vs. Actual <a class="header-anchor" href="#documented-vs-actual-1" aria-label="Permalink to &quot;Documented vs. Actual&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Claim</th><th>Reality</th><th>Match</th></tr></thead><tbody><tr><td>&quot;Handler Structure: Keep handlers thin; place logic in services&quot;</td><td>✅ Handlers are thin; logic is in services</td><td>✅</td></tr><tr><td>&quot;Repository: Data access layer, Service: Business logic&quot;</td><td>❌ No repositories — services do both</td><td>❌</td></tr></tbody></table><hr><h2 id="_3-database-models" tabindex="-1">3. Database &amp; Models <a class="header-anchor" href="#_3-database-models" aria-label="Permalink to &quot;3. Database &amp; Models&quot;">​</a></h2><h3 id="what-works-well-2" tabindex="-1">What Works Well <a class="header-anchor" href="#what-works-well-2" aria-label="Permalink to &quot;What Works Well&quot;">​</a></h3><ul><li><strong>Soft delete strategy</strong> — Consistent <code>deleted_at</code>, <code>deleted_by</code>, <code>delete_reason</code> across users, teams, channels, orgs</li><li><strong>JSONB flexibility</strong> — <code>props</code>, <code>notify_props</code>, <code>entity_metadata</code>, <code>policy_json</code> without schema proliferation</li><li><strong><code>sqlx(default)</code> for evolution</strong> — Non-breaking additive schema changes</li><li><strong>73 migrations since Jan 2026</strong> — Active, healthy development velocity</li><li><strong>Good index coverage</strong> — Channel membership, post time-series, session cleanup</li></ul><h3 id="concerns-2" tabindex="-1">Concerns <a class="header-anchor" href="#concerns-2" aria-label="Permalink to &quot;Concerns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Severity</th><th>Issue</th><th>Details</th></tr></thead><tbody><tr><td>🔴 High</td><td><strong>Severe documentation drift</strong></td><td><code>docs/architecture/data-model.md</code> is months behind: documents non-existent <code>sessions</code> table, wrong column names, missing 10+ entities</td></tr><tr><td>🔴 High</td><td>Model-schema mismatches</td><td><code>TeamMember</code> lacks <code>presence</code> column (added Apr 2026); <code>Post</code> lacks <code>has_reactions</code>; two different <code>Reaction</code> structs</td></tr><tr><td>🟡 Medium</td><td>Epoch timestamp inconsistency</td><td><code>reactions</code>, <code>channel_bookmarks</code>, <code>scheduled_posts</code> use <code>BIGINT</code> epoch millis; rest use <code>TIMESTAMPTZ</code> + <code>DateTime&lt;Utc&gt;</code></td></tr><tr><td>🟡 Medium</td><td><code>activities</code> overly restrictive FKs</td><td><code>channel_id</code>, <code>team_id</code>, <code>post_id</code> are <code>NOT NULL</code> — DMs or deleted contexts will fail</td></tr><tr><td>🟢 Low</td><td><code>UserRole</code> enum unused</td><td><code>User.role</code> is plain <code>String</code>; enum exists but is not used for the DB field</td></tr></tbody></table><hr><h2 id="_4-realtime-websocket-system" tabindex="-1">4. Realtime / WebSocket System <a class="header-anchor" href="#_4-realtime-websocket-system" aria-label="Permalink to &quot;4. Realtime / WebSocket System&quot;">​</a></h2><h3 id="what-works-well-3" tabindex="-1">What Works Well <a class="header-anchor" href="#what-works-well-3" aria-label="Permalink to &quot;What Works Well&quot;">​</a></h3><ul><li><strong>Dual-protocol maturity</strong> — Internal <code>WsEnvelope</code> + Mattermost <code>WebSocketMessage</code> with edge mapping layer</li><li><strong>Cluster broadcast</strong> — Redis pub/sub with echo suppression, auto-reconnect (5s backoff), heartbeat protocol</li><li><strong>Session resumption (v4)</strong> — <code>ConnectionStore</code> with 128-msg ring buffer, 5-min TTL, monotonic <code>seq</code> numbers</li><li><strong>Presence lifecycle</strong> — DB + in-memory + Redis triple-track; manual presence protection; offline only when truly last connection</li><li><strong>TCP resilience</strong> — Unix-specific <code>SO_KEEPALIVE</code> tuning for mobile carrier drops</li></ul><h3 id="concerns-3" tabindex="-1">Concerns <a class="header-anchor" href="#concerns-3" aria-label="Permalink to &quot;Concerns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Severity</th><th>Issue</th><th>Details</th></tr></thead><tbody><tr><td>🔴 High</td><td><strong>Unbounded memory growth</strong></td><td><code>channel_subscriptions</code> and <code>team_subscriptions</code> in <code>WsHub</code> are <strong>never cleaned up</strong> when users disconnect. Code explicitly acknowledges this as a TODO</td></tr><tr><td>🔴 High</td><td>v1 endpoint lacks actor model</td><td>No ping/pong, no write timeouts, no close-code management — relies on OS TCP stack for dead connection detection</td></tr><tr><td>🟡 Medium</td><td><code>broadcast_local</code> holds connections lock during full broadcast</td><td>Can stall <code>add_connection</code> / <code>remove_connection</code> under high load</td></tr><tr><td>🟡 Medium</td><td><code>ConnectionStore::update_subscriptions</code> is a no-op</td><td><code>team_ids</code> / <code>channel_ids</code> fields in <code>ConnectionState</code> are never populated</td></tr><tr><td>🟡 Medium</td><td>Redis subscriber drops messages during reconnect</td><td>5s reconnect window = lost events; no Redis Stream persistence</td></tr><tr><td>🟡 Medium</td><td><code>map_envelope_to_mm</code> silently drops unmapped events</td><td>Compatibility gaps are invisible</td></tr><tr><td>🟢 Low</td><td>Cluster heartbeat exists but is not scheduled</td><td><code>send_heartbeat()</code> defined but never called</td></tr></tbody></table><hr><h2 id="_5-frontend" tabindex="-1">5. Frontend <a class="header-anchor" href="#_5-frontend" aria-label="Permalink to &quot;5. Frontend&quot;">​</a></h2><h3 id="what-works-well-4" tabindex="-1">What Works Well <a class="header-anchor" href="#what-works-well-4" aria-label="Permalink to &quot;What Works Well&quot;">​</a></h3><ul><li><strong>Feature module infrastructure is complete</strong> — 15 features with Repository/Service/Store/Handler separation</li><li><strong>Branded entity IDs</strong> — <code>UserId</code>, <code>ChannelId</code>, <code>MessageId</code> prevent accidental ID mixing</li><li><strong>Railway-oriented <code>Result&lt;T,E&gt;</code></strong> — Clean error handling with <code>success()</code> / <code>failure()</code> helpers</li><li><strong>Custom HTTP client</strong> — Fetch-based with interceptors, timeout, upload progress</li><li><strong>Readonly store exports</strong> — Feature stores use <code>readonly()</code> for unidirectional data flow</li></ul><h3 id="concerns-4" tabindex="-1">Concerns <a class="header-anchor" href="#concerns-4" aria-label="Permalink to &quot;Concerns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Severity</th><th>Issue</th><th>Details</th></tr></thead><tbody><tr><td>🔴 High</td><td><strong>Feature stores are built but unused by UI</strong></td><td>Components import from <code>stores/</code> (legacy), never from <code>features/*/stores/</code>. The new architecture is effectively dead code from the UI perspective</td></tr><tr><td>🔴 High</td><td><strong>Dual WebSocket system</strong></td><td>Legacy <code>useWebSocket.ts</code> (864L, actively used) vs new <code>WebSocketManager.ts</code> (never wired). <code>registerWebSocketHandlers()</code> is never called</td></tr><tr><td>🟡 Medium</td><td>Legacy stores are massive and violate thin-store pattern</td><td><code>stores/calls.ts</code> (1,005L) has WebRTC logic; <code>stores/messages.ts</code> (709L) has author resolution, reaction merging</td></tr><tr><td>🟡 Medium</td><td>Cross-dependency chaos</td><td>Legacy stores import feature stores; feature stores import legacy stores — circular dependency risk</td></tr><tr><td>🟡 Medium</td><td>Two <code>Message</code> types coexist</td><td><code>core/entities/Message.ts</code> (new) and <code>stores/messages.ts</code> <code>Message</code> (legacy) with different shapes</td></tr><tr><td>🟡 Medium</td><td>Components not co-located with features</td><td><code>components/</code> organized by type/topic, not by feature — contradicts documented architecture</td></tr><tr><td>🟡 Medium</td><td>Permissions feature incomplete</td><td>Only <code>capabilities.ts</code> + tests; no repository, service, or store</td></tr></tbody></table><h3 id="documented-vs-actual-2" tabindex="-1">Documented vs. Actual <a class="header-anchor" href="#documented-vs-actual-2" aria-label="Permalink to &quot;Documented vs. Actual&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Claim</th><th>Reality</th><th>Grade</th></tr></thead><tbody><tr><td>&quot;Code organized by feature, not by type&quot;</td><td>Components are by type; features lack components</td><td><strong>C</strong></td></tr><tr><td>&quot;Repository → Service → Store → Handler&quot;</td><td>✅ Built in all mature features</td><td><strong>A</strong></td></tr><tr><td>&quot;Store: State management — thin stores&quot;</td><td>Legacy stores violate this; feature stores are correct</td><td><strong>D</strong> / <strong>A</strong></td></tr><tr><td>&quot;Use branded types for IDs&quot;</td><td>✅ Used in <code>core/entities/</code></td><td><strong>A</strong></td></tr></tbody></table><hr><h2 id="_6-infrastructure-deployment" tabindex="-1">6. Infrastructure &amp; Deployment <a class="header-anchor" href="#_6-infrastructure-deployment" aria-label="Permalink to &quot;6. Infrastructure &amp; Deployment&quot;">​</a></h2><h3 id="what-works-well-5" tabindex="-1">What Works Well <a class="header-anchor" href="#what-works-well-5" aria-label="Permalink to &quot;What Works Well&quot;">​</a></h3><ul><li><strong>Security-first configuration</strong> — <code>.env.example</code> warns against insecure defaults, production secret validation, OAuth code exchange (no URL tokens)</li><li><strong>Push-proxy isolation</strong> — Separate service, Dockerfile, compose file, read-only credential mounts</li><li><strong>CI/CD rigor</strong> — Backend CI with sccache + mold, frontend dependency review, compat diff workflow, multi-arch Docker publish</li><li><strong>Compatibility-first culture</strong> — Governance prohibits agents from touching <code>api/v4/</code> without co-approval; smoke tests verify contracts</li><li><strong>Feature flags for rollout</strong> — Unread v2, post unread WS, etc. are gated with explicit &quot;do not enable in production&quot; warnings</li></ul><h3 id="concerns-5" tabindex="-1">Concerns <a class="header-anchor" href="#concerns-5" aria-label="Permalink to &quot;Concerns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Severity</th><th>Issue</th><th>Details</th></tr></thead><tbody><tr><td>🟡 Medium</td><td>No production Docker Compose</td><td>Same <code>docker-compose.yml</code> for dev and prod — exposes Postgres (5432), Redis (6379), RustFS (9000/9001)</td></tr><tr><td>🟡 Medium</td><td>Missing <code>HEALTHCHECK</code> in main Dockerfiles</td><td>Only <code>backend.Dockerfile.local</code> has one; production images lack it</td></tr><tr><td>🟡 Medium</td><td>No Kubernetes / Helm manifests</td><td>Docs mention K8s support but no official charts exist</td></tr><tr><td>🟡 Medium</td><td>No monitoring stack</td><td>Prometheus mentioned in tech stack but no <code>docker-compose.monitoring.yml</code> or Grafana configs</td></tr><tr><td>🟡 Medium</td><td>CI does not run full-stack E2E</td><td><code>mm_compat_smoke.sh</code> and <code>mm_mobile_smoke.sh</code> are not run in CI</td></tr><tr><td>🟡 Medium</td><td>No automated backup/DR</td><td>Manual <code>pg_dump</code> mentioned; no cron or automated scripts</td></tr><tr><td>🟢 Low</td><td>Frontend uses OpenResty unnecessarily</td><td><code>nginx.conf</code> does not use Lua features; adds image size without benefit</td></tr></tbody></table><hr><h2 id="cross-cutting-themes" tabindex="-1">Cross-Cutting Themes <a class="header-anchor" href="#cross-cutting-themes" aria-label="Permalink to &quot;Cross-Cutting Themes&quot;">​</a></h2><h3 id="theme-1-migration-limbo" tabindex="-1">Theme 1: Migration Limbo <a class="header-anchor" href="#theme-1-migration-limbo" aria-label="Permalink to &quot;Theme 1: Migration Limbo&quot;">​</a></h3><p>The most pervasive issue across the codebase is <strong>partial migrations that were never completed</strong>:</p><ul><li><strong>Frontend:</strong> Feature architecture built but UI still on legacy stores</li><li><strong>Backend:</strong> One <code>PolicyRepository</code> exists as a proof of concept, but no broader repository layer adoption</li><li><strong>WebSocket:</strong> New <code>WebSocketManager</code> built but never wired into the app</li><li><strong>Unread system:</strong> v2 hash schema built alongside legacy string keys</li></ul><h3 id="theme-2-documentation-drift" tabindex="-1">Theme 2: Documentation Drift <a class="header-anchor" href="#theme-2-documentation-drift" aria-label="Permalink to &quot;Theme 2: Documentation Drift&quot;">​</a></h3><p>Multiple architecture documents are stale or misleading:</p><ul><li><code>docs/architecture/data-model.md</code> — severely outdated (wrong tables, wrong columns, missing entities)</li><li><code>docs/architecture/frontend.md</code> — describes the target state, not the actual mixed legacy/feature reality</li><li>Migration naming docs claim &quot;numbered sequentially&quot; but actual files use timestamps</li></ul><h3 id="theme-3-rapid-growth-outpacing-organization" tabindex="-1">Theme 3: Rapid Growth Outpacing Organization <a class="header-anchor" href="#theme-3-rapid-growth-outpacing-organization" aria-label="Permalink to &quot;Theme 3: Rapid Growth Outpacing Organization&quot;">​</a></h3><p>The codebase grew from a clean prototype to a feature-rich platform without corresponding organizational refactoring:</p><ul><li><code>posts.rs</code> (1,037L) accumulated 7+ responsibilities</li><li><code>admin.rs</code> (2,591L) and <code>calls_plugin/mod.rs</code> (4,234L) are single files doing the work of modules</li><li>73 migrations in ~4 months indicates very high velocity, but some schema decisions (epoch timestamps, <code>activities</code> FKs) suggest insufficient design review</li></ul><h3 id="theme-4-production-readiness-gaps" tabindex="-1">Theme 4: Production Readiness Gaps <a class="header-anchor" href="#theme-4-production-readiness-gaps" aria-label="Permalink to &quot;Theme 4: Production Readiness Gaps&quot;">​</a></h3><p>The project is clearly optimized for development velocity and small-scale Docker Compose deployments. Production-grade concerns (network isolation, K8s, monitoring, automated backups, full-stack CI) are documented as concepts but not materialized as version-controlled infrastructure.</p><hr><h2 id="prioritized-recommendations" tabindex="-1">Prioritized Recommendations <a class="header-anchor" href="#prioritized-recommendations" aria-label="Permalink to &quot;Prioritized Recommendations&quot;">​</a></h2><h3 id="immediate-this-sprint" tabindex="-1">Immediate (This Sprint) <a class="header-anchor" href="#immediate-this-sprint" aria-label="Permalink to &quot;Immediate (This Sprint)&quot;">​</a></h3><ol><li><strong>Fix model-schema mismatches</strong> — Add <code>presence</code> to <code>TeamMember</code>, <code>has_reactions</code> to <code>Post</code>, reconcile <code>Reaction</code> structs</li><li><strong>Wire new WebSocket manager</strong> — Replace legacy <code>useWebSocket.ts</code> with <code>WebSocketManager.ts</code> + feature handlers</li><li><strong>Add <code>HEALTHCHECK</code> to production Dockerfiles</strong></li></ol><h3 id="short-term-next-2-sprints" tabindex="-1">Short-Term (Next 2 Sprints) <a class="header-anchor" href="#short-term-next-2-sprints" aria-label="Permalink to &quot;Short-Term (Next 2 Sprints)&quot;">​</a></h3><ol start="4"><li><strong>Extract repository layer from <code>posts.rs</code></strong> — Separate data access from business logic; use as template for other services</li><li><strong>Clean up <code>WsHub</code> subscription maps</strong> — Add periodic cleanup task or track subscriptions per-connection</li><li><strong>Rewrite <code>docs/architecture/data-model.md</code></strong> — Sync with actual schema</li><li><strong>Add <code>docker-compose.prod.yml</code></strong> — Remove exposed DB/Redis ports, add resource limits</li></ol><h3 id="medium-term-next-quarter" tabindex="-1">Medium-Term (Next Quarter) <a class="header-anchor" href="#medium-term-next-quarter" aria-label="Permalink to &quot;Medium-Term (Next Quarter)&quot;">​</a></h3><ol start="8"><li><strong>Complete frontend migration</strong> — Migrate component imports from <code>stores/*</code> to <code>features/*</code></li><li><strong>Extract <code>api/mod.rs</code> startup logic</strong> — Move background worker spawns to <code>main.rs</code> or dedicated startup module</li><li><strong>Add Prometheus + Grafana stack</strong> — <code>docker-compose.monitoring.yml</code> with basic dashboards</li><li><strong>Add full-stack E2E to CI</strong> — Spin up compose stack, run smoke tests</li></ol><h3 id="long-term" tabindex="-1">Long-Term <a class="header-anchor" href="#long-term" aria-label="Permalink to &quot;Long-Term&quot;">​</a></h3><ol start="12"><li><strong>Kubernetes Helm chart</strong> — For production deployments</li><li><strong>Unify timestamp conventions</strong> — Migrate epoch-millis tables to <code>TIMESTAMPTZ</code></li><li><strong>Service traits for testability</strong> — Define async traits for core services to enable mocking</li></ol><hr><p><em>Analysis conducted via parallel codebase exploration of backend API, services, database, realtime, frontend, and infrastructure layers, cross-referenced with existing architecture documentation.</em></p>',74)])])}const g=t(d,[["render",s]]);export{m as __pageData,g as default};
